semantic_results = ["chunk_3", "chunk_1", "chunk_5", "chunk_2"]
keyword_results = ["chunk_1", "chunk_4", "chunk_3", "chunk_2"]

def reciprocal_rank_fusion(result_lists, k=60):
    scores = {}
    for results in result_lists:
        for rank, chunk_id in enumerate(results, start=1):
            scores[chunk_id] = scores.get(chunk_id, 0) + 1 / (k + rank)
    return sorted(scores.items(), key=lambda x: -x[1])

merged = reciprocal_rank_fusion([semantic_results, keyword_results])

print("Semantic search results:", semantic_results)
print("Keyword search results:", keyword_results)
print("\nMerged hybrid results:")
for chunk_id, score in merged:
    print(f"  {chunk_id}: {score:.4f}")
